/*
 * test_multivector_fidelity.cpp - multivector runtime against pylate
 *
 * Compares, per token, the vectors of the C runtime with golden vectors
 * generated by pylate (tests/data/colbert/gen_golden.py ->
 * answerai_small_golden.json, rounded to 3 decimals). Same vector counts and a
 * per-token cosine >= 0.999 are required.
 *
 * Skipped (exit 0) when the model directory is absent (LEMBED_COLBERT_MODEL_DIR,
 * else ~/.cache/libembedding/models--answerdotai-answerai-colbert-small-v1).
 * The three query modes are measured and printed; the default configuration
 * must be the one that reproduces the reference.
 *
 * Auteur: David Orel
 * Version: 1.16.0
 *
 * SPDX-License-Identifier: MIT
 */

#ifndef _WIN32
#define LIBEMBEDDING_IMPLEMENTATION
#endif
#include <libembedding/libembedding.h>

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

#ifndef LEMBED_TEST_DATA_DIR
#define LEMBED_TEST_DATA_DIR "data"
#endif

static int passes = 0, failures = 0;

#define ASSERT(cond, msg) do { \
    if (!(cond)) { \
        fprintf(stderr, "FAIL: %s (line %d)\n", msg, __LINE__); \
        failures++; \
    } else { \
        passes++; \
    } \
} while (0)

struct Golden {
    std::string text;
    std::vector<float> flat;   /* rows x dim */
    int rows = 0;
};

/* Reads the fixed layout written by gen_golden.py:
 * {"queries":[{"text":"...","vectors":[[..],..]},..],"docs":[...]} */
static bool read_section(const std::string& js, const char* key, std::vector<Golden>& out) {
    size_t p = js.find(std::string("\"") + key + "\":[");
    if (p == std::string::npos) return false;
    p += strlen(key) + 4;
    const size_t section_end = js.find("]}]", p);
    while (true) {
        const size_t t = js.find("\"text\":\"", p);
        if (t == std::string::npos || (section_end != std::string::npos && t > section_end)) break;
        Golden g;
        const size_t ts = t + 8;
        const size_t te = js.find('"', ts);
        g.text = js.substr(ts, te - ts);
        size_t v = js.find("\"vectors\":[", te) + 11;
        /* rows: "[n,n,...]," */
        while (js[v] == '[') {
            v++;
            while (js[v] != ']') {
                char* endp = nullptr;
                g.flat.push_back((float)strtod(js.c_str() + v, &endp));
                v = (size_t)(endp - js.c_str());
                if (js[v] == ',') v++;
            }
            v++;                       /* ] of the row */
            g.rows++;
            if (js[v] == ',') v++;
        }
        out.push_back(g);
        p = v;
    }
    return !out.empty();
}

static double cosine(const float* a, const float* b, int dim) {
    double ab = 0, aa = 0, bb = 0;
    for (int i = 0; i < dim; i++) { ab += (double)a[i] * b[i]; aa += (double)a[i] * a[i]; bb += (double)b[i] * b[i]; }
    return ab / (std::sqrt(aa) * std::sqrt(bb) + 1e-30);
}

/* Minimum per-token cosine, or -2 when a vector count differs. */
static double min_cosine(lembed_multivector_t* mv, lembed_mv_mode_t mode,
                         const std::vector<Golden>& ref, const char* label) {
    double worst = 1.0;
    for (size_t i = 0; i < ref.size(); i++) {
        const char* t[] = { ref[i].text.c_str() };
        lembed_multivectors_t r;
        if (lembed_multivector_embed(mv, t, 1, mode, &r) != LEMBED_OK) {
            fprintf(stderr, "embed failed: %s\n", lembed_last_error());
            return -3.0;
        }
        if ((int)r.total_vectors != ref[i].rows || r.dim * ref[i].rows != (int)ref[i].flat.size()) {
            printf("  %s[%zu] \"%s\": %d vectors, reference %d\n", label, i, ref[i].text.c_str(),
                   (int)r.total_vectors, ref[i].rows);
            lembed_multivectors_free(&r);
            return -2.0;
        }
        for (int j = 0; j < ref[i].rows; j++)
            worst = std::min(worst, cosine(r.data + (size_t)j * r.dim, ref[i].flat.data() + (size_t)j * r.dim, r.dim));
        lembed_multivectors_free(&r);
    }
    return worst;
}

int main(void) {
    std::string dir;
    if (const char* e = getenv("LEMBED_COLBERT_MODEL_DIR")) dir = e;
    if (dir.empty()) {
        const char* home = getenv("USERPROFILE");
        if (!home || !home[0]) home = getenv("HOME");
        if (home && home[0])
            dir = std::string(home) + "/.cache/libembedding/models--answerdotai-answerai-colbert-small-v1";
    }
    if (dir.empty() || !std::filesystem::exists(std::filesystem::path(dir) / "tokenizer.json")) {
        printf("SKIP: model directory not found (%s)\n", dir.c_str());
        return 0;
    }

    std::ifstream f(std::string(LEMBED_TEST_DATA_DIR) + "/colbert/answerai_small_golden.json", std::ios::binary);
    if (!f) { fprintf(stderr, "FAIL: golden fixture not found\n"); return 1; }
    std::stringstream ss;
    ss << f.rdbuf();
    const std::string js = ss.str();

    std::vector<Golden> queries, docs;
    ASSERT(read_section(js, "queries", queries) && queries.size() == 3, "3 golden queries");
    ASSERT(read_section(js, "docs", docs) && docs.size() == 3, "3 golden docs");
    if (failures) return 1;

    struct Mode { const char* name; int expansion; int attend; };
    const Mode modes[] = {
        { "expansion, pads masked out (attend=0)", 1, 0 },
        { "expansion, pads attended  (attend=1)", 1, 1 },
        { "no expansion", 0, 0 },
    };
    printf("model: %s\n", dir.c_str());
    double best = -9;
    for (const Mode& m : modes) {
        lembed_multivector_options_t o = lembed_multivector_options_default();
        o.model_dir = dir.c_str();
        o.query_expansion = m.expansion;
        o.attend_to_expansion = m.attend;
        lembed_multivector_t* mv = nullptr;
        ASSERT(lembed_multivector_create(&o, &mv) == LEMBED_OK, "create");
        if (!mv) return 1;
        const double c = min_cosine(mv, LEMBED_MV_QUERY, queries, "query");
        printf("query mode [%s]: min per-token cosine = %.6f\n", m.name, c);
        best = std::max(best, c);
        lembed_multivector_free(mv);
    }

    /* Documents do not depend on the query mode. */
    {
        lembed_multivector_options_t o = lembed_multivector_options_default();
        o.model_dir = dir.c_str();
        lembed_multivector_t* mv = nullptr;
        ASSERT(lembed_multivector_create(&o, &mv) == LEMBED_OK, "create default");
        if (!mv) return 1;
        const double cd = min_cosine(mv, LEMBED_MV_DOCUMENT, docs, "doc");
        printf("documents: min per-token cosine = %.6f\n", cd);
        ASSERT(cd >= 0.999, "documents: per-token cosine >= 0.999 with identical vector counts");

        const double cq = min_cosine(mv, LEMBED_MV_QUERY, queries, "query");
        printf("queries (default options): min per-token cosine = %.6f\n", cq);
        ASSERT(cq >= 0.999, "queries, default options: per-token cosine >= 0.999 with identical vector counts");
        lembed_multivector_free(mv);
    }
    ASSERT(best >= 0.999, "at least one query mode reproduces the reference");

    printf("%d passed, %d failed\n", passes, failures);
    return failures > 0 ? 1 : 0;
}
